509	    "書き込みを止めずに索引を作る（例: CREATE INDEX CONCURRENTLY）",
510	    "大量の行の書き換えは、少しずつ行う"].forEach((t, i) => {
511	    badge(s, i + 1, 0.5, 3.12 + i * 0.5, 0.32, { fill: OK });
512	    text(s, t, 0.95, 3.1 + i * 0.5, 8.5, 0.36, { fontSize: 14, valign: "middle" });
513	  });
514	  takeaway(s, "大きな表の変更は、ロックを長く持たない形で行う");
515	  s.addNotes("migration は表のロックを取ることがある。索引の作成や大量の行の書き換えが長くかかると、その間、その表への書き込みが待たされ、新旧どちらのコードの要求もタイムアウトでエラーになる。対策の例は、ロックを待つ時間に上限を設けること（PostgreSQL の lock_timeout）、書き込みを止めずに索引を作ること（CREATE INDEX CONCURRENTLY）、大量の行の書き換えを少しずつ行うこと。");
516	}
517	{
518	  const s = content(SEC4, SEC4, "新しい値を書き始める変更は、2 回のリリースに分ける");
519	  text(s, "状態の列 status の値:", 0.5, 1.4, 2.4, 0.4, { fontSize: 13, color: MUTED, valign: "middle" });
520	  box(s, 2.9, 1.4, 1.0, 0.4, "draft", { fill: PANEL, fontSize: 12 });
521	  box(s, 4.0, 1.4, 1.0, 0.4, "done", { fill: PANEL, fontSize: 12 });
522	  box(s, 5.1, 1.4, 2.4, 0.4, "paused（新しい値）", { fill: NEW, color: WHITE, fontSize: 12, bold: true });
523	  badge(s, "×", 0.5, 2.22, 0.4, { fill: BAD, fontSize: 16 });

