// 無停止リリースの説明資料を作る。
// 実行: NODE_PATH=<deckbuild>/node_modules node build.js <出力ファイル>
const path = require("path");
const pptxgen = require("pptxgenjs");
const SKILL = process.env.PPTX_SKILL_DIR;
const { applyTheme } = require(path.join(SKILL, "scripts/apply_theme.js"));

const OUT = process.argv[2] || "zero-downtime.pptx";

const THEME = {
  name: "ZeroDowntime",
  headFontFace: "Noto Sans JP",
  bodyFontFace: "Noto Sans JP",
  colors: {
    dk1: "1F2933", lt1: "FFFFFF", dk2: "52606D", lt2: "F2F4F7",
    accent1: "0F8B8D", // 新しい版
    accent2: "7B8794", // 古い版
    accent3: "D9480F", // 失敗・壊す
    accent4: "2F9E44", // 安全・成功
    accent5: "F0A202", // 新旧が重なる期間
    accent6: "1C3D5A", // DB と migration
    hlink: "0F6E8C", folHlink: "6B4F9E",
  },
};

const pres = new pptxgen();
pres.layout = "LAYOUT_16x9"; // 10 x 5.625 インチ
pres.title = "無停止リリースと、アプリケーションの作り方";
pres.theme = { headFontFace: THEME.headFontFace, bodyFontFace: THEME.bodyFontFace };
const C = pres.SchemeColor;
const NEW = C.accent1, OLD = C.accent2, BAD = C.accent3, OK = C.accent4,
  OVERLAP = C.accent5, DB = C.accent6, TEXT = C.text1, MUTED = C.text2,
  PANEL = C.background2, WHITE = C.background1;
const S = pres.shapes;

// ---- レイアウト ----
pres.defineSlideMaster({
  title: "TITLE",
  background: { color: "1C3D5A" },
  objects: [
    { placeholder: { options: { name: "title", type: "title", x: 0.6, y: 1.35, w: 8.8, h: 1.1,
      fontSize: 32, bold: true, color: WHITE, valign: "bottom", margin: 0 }, text: "" } },
    { placeholder: { options: { name: "sub", type: "body", x: 0.6, y: 2.55, w: 8.8, h: 0.5,
      fontSize: 16, color: WHITE, valign: "top", margin: 0 }, text: "" } },
  ],
});
pres.defineSlideMaster({
  title: "CONTENT",
  background: { color: "FFFFFF" },
  objects: [
    { placeholder: { options: { name: "kicker", type: "body", x: 0.5, y: 0.28, w: 9, h: 0.3,
      fontSize: 12, bold: true, color: NEW, valign: "middle", margin: 0 }, text: "" } },
    { placeholder: { options: { name: "title", type: "title", x: 0.5, y: 0.58, w: 9, h: 0.62,
      fontSize: 24, bold: true, color: TEXT, valign: "middle", margin: 0 }, text: "" } },
  ],
  slideNumber: { x: 9.1, y: 5.2, w: 0.5, h: 0.3, fontSize: 10, color: MUTED, align: "right" },
});

// ---- 描画の部品 ----
function box(s, x, y, w, h, t, o = {}) {
  const shape = o.shape || S.ROUNDED_RECTANGLE;
  const opt = {
    shape, x, y, w, h,
    fill: { color: o.fill || WHITE, transparency: o.tr || 0 },
    color: o.color || TEXT, fontSize: o.fontSize || 14, bold: !!o.bold,
    align: o.align || "center", valign: o.valign || "middle",
    margin: o.margin === undefined ? 6 : o.margin, // ポイント
    objectName: o.name,
  };
  if (shape === S.ROUNDED_RECTANGLE) opt.rectRadius = o.radius === undefined ? 0.08 : o.radius;
  if (o.line) opt.line = { color: o.line, width: o.lineW || 1, dashType: o.dash };
  s.addText(t, opt);
}
function text(s, t, x, y, w, h, o = {}) {
  s.addText(t, {
    x, y, w, h, isTextBox: true, fontSize: o.fontSize || 14, color: o.color || TEXT,
    bold: !!o.bold, align: o.align || "left", valign: o.valign || "top",
    margin: o.margin === undefined ? 0 : o.margin, objectName: o.name,
    paraSpaceAfter: o.psa,
  });
}
function arrow(s, x1, y1, x2, y2, o = {}) {
  s.addShape(S.LINE, {
    x: Math.min(x1, x2), y: Math.min(y1, y2), w: Math.abs(x2 - x1), h: Math.abs(y2 - y1),
    flipH: x2 < x1, flipV: y2 < y1,
    line: { color: o.color || MUTED, width: o.width || 1.5, dashType: o.dash,
      endArrowType: o.noHead ? undefined : "triangle", beginArrowType: o.both ? "triangle" : undefined },
  });
}
function badge(s, n, x, y, d, o = {}) {
  s.addText(String(n), { shape: S.OVAL, x, y, w: d, h: d, fill: { color: o.fill || NEW },
    color: WHITE, fontSize: o.fontSize || 12, bold: true, align: "center", valign: "middle", margin: 0 });
}
function takeaway(s, t) {
  text(s, t, 0.5, 4.78, 8.5, 0.42, { fontSize: 14, bold: true, color: TEXT, valign: "middle", name: "takeaway" });
}
function content(section, kicker, title) {
  const s = pres.addSlide({ masterName: "CONTENT", sectionTitle: section });
  s.addText(kicker, { placeholder: "kicker" });
  s.addText(title, { placeholder: "title" });
  return s;
}
function bullets(items, o = {}) {
  return items.map((t, i) => ({ text: t, options: { bullet: true, breakLine: i < items.length - 1,
    fontSize: o.fontSize || 14, color: o.color || TEXT } }));
}
function card(s, x, y, w, h, o = {}) {
  s.addShape(S.ROUNDED_RECTANGLE, { x, y, w, h, rectRadius: 0.1,
    fill: { color: o.fill || PANEL, transparency: o.tr || 0 }, objectName: o.name });
}

// ======== 表紙 ========
pres.addSection({ title: "表紙" });
{
  const s = pres.addSlide({ masterName: "TITLE", sectionTitle: "表紙" });
  s.addText("無停止リリースと、\nアプリケーションの作り方", { placeholder: "title" });
  s.addText("Cloud Run と DB マイグレーションを例に", { placeholder: "sub" });
  s.addShape(S.RECTANGLE, { x: 3.6, y: 3.7, w: 2.4, h: 0.95, fill: { color: OVERLAP, transparency: 25 } });
  s.addShape(S.ROUNDED_RECTANGLE, { x: 0.6, y: 3.82, w: 5.4, h: 0.26, rectRadius: 0.13, fill: { color: OLD } });
  s.addShape(S.ROUNDED_RECTANGLE, { x: 3.6, y: 4.27, w: 5.8, h: 0.26, rectRadius: 0.13, fill: { color: NEW } });
  text(s, "古い版", 0.6, 3.45, 1.5, 0.3, { fontSize: 12, color: WHITE });
  text(s, "新しい版", 7.9, 4.6, 1.5, 0.3, { fontSize: 12, color: WHITE, align: "right" });
  s.addNotes("この資料は、無停止リリースがなぜ大事か、Cloud Run でデプロイするときに何が起きるか、そのためにアプリケーションと DB マイグレーションを作るときに何に気をつけるかを説明する。表紙の 2 本の帯は、古い版と新しい版が同時に動く期間を表していて、資料の全体で同じ色を使う（灰色が古い版、青緑が新しい版、黄色が重なる期間）。細かな規則はプロジェクトごとに決めるので、ここでは扱わない。");
}
{
  const s = content("表紙", "この資料の前提", "例は PostgreSQL だが、考え方は NoSQL でも同じ");
  box(s, 0.5, 1.4, 9.0, 0.6, "どの DB でも、デプロイの間は新旧のコードが同じデータを読み書きする",
    { fill: OVERLAP, tr: 60, fontSize: 15, bold: true });
  arrow(s, 2.65, 2.0, 2.65, 2.3);
  arrow(s, 7.35, 2.0, 7.35, 2.3);
  [[0.5, "RDB（例: PostgreSQL）", ["表と列を DB に定義する", "migration で定義を変える"]],
    [5.2, "NoSQL（例: Firestore、MongoDB）", ["データの形は、コードで決まる", "古い形と新しい形のデータが混ざる"]]].forEach(([x, h, items]) => {
    card(s, x, 2.3, 4.3, 1.7);
    box(s, x, 2.3, 4.3, 0.45, h, { shape: S.RECTANGLE, fill: DB, color: WHITE, fontSize: 14, bold: true });
    s.addText(bullets(items), { x: x + 0.25, y: 2.9, w: 3.9, h: 0.95, isTextBox: true,
      valign: "top", margin: 0, paraSpaceAfter: 6 });
  });
  text(s, "ロックの待ちなど RDB に特有の例は、NoSQL では索引の作成や書き込みの上限など、別の形で起きる",
    0.5, 4.12, 9.0, 0.4, { fontSize: 12, color: MUTED, valign: "middle" });
  takeaway(s, "具体的な注意は DB ごとに違うが、守る考え方は同じ");
  s.addNotes("この資料の例は、RDB（リレーショナルデータベース）の PostgreSQL を使う。ただし、考え方は NoSQL（Firestore や MongoDB など、表と列の定義を DB が強制しないことが多いデータベース）でも同じ。どの DB でも、デプロイの間は古いコードと新しいコードが同じデータを読み書きする。RDB では表と列を DB に定義し、migration で定義を変える。NoSQL では、データの形はコードが書き込む内容で決まるので、古い形のデータと新しい形のデータが混ざって残り、コードはどちらも扱える必要がある。古いコードが使っているフィールドを変えない・消さないこと、壊す変更を拡張 → 移行 → 縮小に分けること、新しい値を読める版を先にリリースすること、データは戻しにくいことは、NoSQL でも同じ。一方、表のロックの待ちや「SELECT *」の話は RDB の例で、NoSQL では、索引の作成に時間がかかること、大量の書き換えが書き込みの上限（スループット）に達すること、知らないフィールドがあると失敗する読み込みの設定など、別の形で同じ種類の問題が起きる。");
}

// ======== 1. なぜ無停止か ========
const SEC1 = "1. なぜ無停止か";
pres.addSection({ title: SEC1 });
{
  const s = content(SEC1, SEC1, "停止するリリースは、関係者全員の時間を使う");
  const cxs = [1.9, 5.0, 8.1], who = ["お客様", "運用担当者", "開発者"];
  const loads = [
    ["止まる間は使えない", "業務の予定を合わせる"],
    ["夜間・休日に作業する", "再開を確認する"],
    ["作業に立ち会う", "手順を準備する"],
  ];
  cxs.forEach((cx, i) => {
    s.addText(who[i], { shape: S.OVAL, x: cx - 0.6, y: 1.4, w: 1.2, h: 1.2, fill: { color: MUTED },
      color: WHITE, fontSize: 15, bold: true, align: "center", valign: "middle", margin: 0 });
    card(s, cx - 1.3, 2.85, 2.6, 1.55);
    s.addText(bullets(loads[i]), { x: cx - 1.15, y: 3.0, w: 2.35, h: 1.25, isTextBox: true,
      valign: "top", margin: 0, paraSpaceAfter: 6 });
  });
  arrow(s, 2.55, 2.0, 4.35, 2.0, { both: true });
  arrow(s, 5.65, 2.0, 7.45, 2.0, { both: true });
  text(s, "停止の告知・日程の調整", 2.45, 1.55, 2.0, 0.35, { fontSize: 12, color: MUTED, align: "center" });
  text(s, "作業の日時の調整", 5.55, 1.55, 2.0, 0.35, { fontSize: 12, color: MUTED, align: "center" });
  takeaway(s, "止めるたびに関係者全員の調整が要り、管理のコストが増える");
  s.addNotes("リリースのたびにサービスを止めると、お客様には停止を告知し、業務の予定を合わせてもらう必要がある。運用担当者は、利用の少ない夜間や休日に作業し、再開を確認する。開発者も作業に立ち会う。止めるたびに、この調整が関係者全員に発生し、管理のコストになる。");
}
{
  const s = content(SEC1, SEC1, "無停止なら、リリースは普段の作業になる");
  text(s, "停止するリリース", 0.5, 1.4, 4, 0.3, { fontSize: 14, bold: true, color: MUTED });
  const steps = ["事前に告知する", "日程を調整する", "夜間に止めて\n作業する", "再開を確認する"];
  steps.forEach((t, i) => {
    box(s, 0.5 + i * 2.27, 1.75, 2.2, 0.75, t, { shape: i === 0 ? S.PENTAGON : S.CHEVRON,
      fill: OLD, color: WHITE, fontSize: 13, bold: true, margin: [0, 20, 0, 20] });
  });
  text(s, "無停止のリリース", 0.5, 2.85, 4, 0.3, { fontSize: 14, bold: true, color: NEW });
  box(s, 0.5, 3.2, 2.2, 0.75, "日中にデプロイする", { shape: S.PENTAGON, fill: NEW, color: WHITE,
    fontSize: 13, bold: true, margin: [0, 20, 0, 8] });
  text(s, "利用は止まらないので、停止の調整が要らない", 2.95, 3.2, 6.5, 0.75, { fontSize: 15, valign: "middle" });
  takeaway(s, "リリースが、普段の開発の作業の一部になる");
  s.addNotes("停止するリリースは、告知・日程の調整・夜間の作業・再開の確認という手順を毎回踏む。無停止のリリースなら、日中にデプロイしても利用が止まらないので、停止のための調整が要らない。リリースを、特別な行事ではなく、普段の開発の作業として行えるようになる。");
}

// ======== 2. 無停止デプロイの方式 ========
const SEC2 = "2. 無停止デプロイの方式";
pres.addSection({ title: SEC2 });
{
  const s = content(SEC2, SEC2, "ブルーグリーンデプロイ: 環境を 2 つ用意して切り替える");
  box(s, 4.0, 1.35, 2.0, 0.45, "利用者", { fill: PANEL, fontSize: 13 });
  arrow(s, 5.0, 1.8, 5.0, 2.05);
  box(s, 3.75, 2.05, 2.5, 0.5, "ロードバランサー", { fill: MUTED, color: WHITE, fontSize: 13, bold: true });
  box(s, 1.3, 3.0, 2.8, 0.7, "ブルー環境（今の版）", { fill: OLD, color: WHITE, bold: true });
  box(s, 5.9, 3.0, 2.8, 0.7, "グリーン環境（新しい版）", { fill: NEW, color: WHITE, bold: true });
  arrow(s, 4.4, 2.55, 2.9, 3.0, { color: OLD, width: 2 });
  arrow(s, 5.6, 2.55, 7.1, 3.0, { color: NEW, width: 2, dash: "dash" });
  text(s, "向き先を切り替える", 6.45, 2.45, 2.2, 0.3, { fontSize: 12, color: NEW, bold: true });
  box(s, 4.3, 3.95, 1.4, 0.7, "DB", { shape: S.CAN, fill: DB, color: WHITE, bold: true });
  arrow(s, 2.7, 3.7, 4.3, 4.3, { noHead: true });
  arrow(s, 7.3, 3.7, 5.7, 4.3, { noHead: true });
  takeaway(s, "すぐに戻せるが、同じ構成の環境が 2 つ要る");
  s.addNotes("ブルーグリーンデプロイは、今の版が動く環境（ブルー）とは別に、新しい版の環境（グリーン）を用意し、ロードバランサーの向き先を切り替える方式。問題があれば向き先を戻すだけで済むが、同じ構成の環境を 2 つ持つので、リソースは 2 倍要る。DB は、ふつうは 2 つの環境で 1 つを共有する。");
}
{
  const s = content(SEC2, SEC2, "ローリングアップデート: 1 台ずつ入れ替える");
  const rows = [0, 1, 3, 4];
  s.addShape(S.RECTANGLE, { x: 0.95, y: 2.13, w: 5.95, h: 1.34, fill: { color: OVERLAP, transparency: 75 } });
  rows.forEach((nNew, r) => {
    const y = 1.45 + r * 0.75;
    badge(s, r + 1, 0.5, y + 0.07, 0.32, { fill: MUTED });
    for (let i = 0; i < 4; i++) {
      const isNew = i < nNew;
      box(s, 1.1 + i * 1.05, y, 0.95, 0.45, isNew ? "新" : "旧", { fill: isNew ? NEW : OLD, color: WHITE,
        fontSize: 13, bold: true });
    }
  });
  text(s, "新旧が混ざる", 5.35, 2.6, 1.5, 0.4, { fontSize: 14, bold: true, valign: "middle" });
  arrow(s, 6.95, 2.85, 7.7, 2.85);
  box(s, 7.7, 2.4, 1.2, 0.9, "DB", { shape: S.CAN, fill: DB, color: WHITE, bold: true });
  text(s, "DB は 1 つ", 7.5, 3.4, 1.6, 0.3, { fontSize: 12, color: MUTED, align: "center" });
  takeaway(s, "追加の環境は要らないが、台数と入れ替えの手順を管理する");
  s.addNotes("ローリングアップデートは、何台かのサーバーを 1 台ずつ新しい版に入れ替える方式。追加の環境は要らないが、入れ替えの途中は、古い版と新しい版のサーバーが混ざって動く。台数を確保し、入れ替えの手順を管理する必要がある。");
}
{
  const s = content(SEC2, SEC2, "どちらの方式も、小さなシステムには向かない");
  card(s, 0.5, 1.4, 5.3, 2.2);
  text(s, "自分たちで用意し、運用し続けるもの", 0.75, 1.55, 4.9, 0.35, { fontSize: 14, bold: true });
  ["2 つ目の環境（ブルーグリーン）", "切り替えの仕組み（ロードバランサー）", "入れ替えの手順と、その監視"].forEach((t, i) => {
    badge(s, i + 1, 0.75, 2.05 + i * 0.48, 0.32, { fill: MUTED });
    text(s, t, 1.2, 2.03 + i * 0.48, 4.5, 0.36, { fontSize: 14, valign: "middle" });
  });
  card(s, 6.2, 1.4, 3.3, 2.2);
  text(s, "小さなシステム", 6.45, 1.55, 2.9, 0.35, { fontSize: 14, bold: true });
  s.addText(bullets(["台数が少ない", "運用の人手が少ない"]), { x: 6.45, y: 2.0, w: 2.9, h: 0.8,
    isTextBox: true, valign: "top", margin: 0, paraSpaceAfter: 6 });
  text(s, "手間とコストが見合わない", 6.45, 2.95, 2.9, 0.45, { fontSize: 14, bold: true, color: BAD, valign: "middle" });
  card(s, 0.5, 3.85, 9.0, 0.8, { fill: OVERLAP, tr: 75 });
  text(s, "どちらの方式でも DB は 1 つ。新旧のコードが同じ DB を使う期間は無くならない", 0.75, 3.85, 8.6, 0.8,
    { fontSize: 15, bold: true, valign: "middle" });
  s.addNotes("どちらの方式も、2 つ目の環境や切り替えの仕組みを自分たちで用意し、運用し続ける必要がある。台数も運用の人手も少ない小さなシステムでは、その手間とコストが見合わない。また、どちらの方式でも DB はふつう 1 つなので、新旧のコードが同じ DB を使う期間は無くならない。この点は、どの方式を選んでもアプリケーションの側で考える必要がある（「4. DB マイグレーション」）。");
}
{
  const s = content(SEC2, SEC2, "Cloud Run では、切り替えを基盤が行う");
  box(s, 0.6, 2.25, 1.4, 0.6, "利用者", { fill: PANEL, fontSize: 13 });
  arrow(s, 2.0, 2.55, 2.5, 2.55);
  box(s, 2.5, 2.05, 2.0, 1.0, "Cloud Run の\nサービス", { fill: MUTED, color: WHITE, bold: true });
