  box(s, 0.7, 3.0, 2.1, 0.55, "古いコード", { fill: OLD, color: WHITE, fontSize: 13, bold: true });
  box(s, 0.7, 3.85, 2.1, 0.55, "新しいコード", { fill: NEW, color: WHITE, fontSize: 13, bold: true });
  arrow(s, 2.8, 3.275, 3.8, 3.55);
  arrow(s, 2.8, 4.125, 3.8, 3.85);
  box(s, 3.8, 3.05, 1.6, 1.3, "DB\n新しいスキーマ", { shape: S.CAN, fill: DB, color: WHITE, fontSize: 13, bold: true });
  card(s, 5.9, 2.9, 3.6, 1.6);
  s.addText([{ text: "約 15 秒・496 件", options: { fontSize: 24, bold: true, color: DB } }],
    { x: 6.1, y: 3.0, w: 3.3, h: 0.5, isTextBox: true, margin: 0, valign: "middle" });
