{
  const s = content(SEC4, SEC4, "列の追加でも、古いコードが失敗することがある");
  const flow = [
    ["古いコードが「SELECT *」（すべての列）の文を保存して使い回す", { fill: OLD, color: WHITE }],
    ["列を追加する migration を適用する", { fill: DB, color: WHITE }],
    ["結果の列の構成が変わり、DB がその文を実行しない", { fill: BAD, tr: 85, line: BAD }],
    ["その文を使う要求がエラーになる", { fill: BAD, color: WHITE }],
  ];
  flow.forEach(([t, o], i) => {
    box(s, 0.5 + i * 2.33, 1.45, 2.05, 1.15, t, Object.assign({ fontSize: 13, bold: true }, o));
    if (i < 3) arrow(s, 2.55 + i * 2.33, 2.025, 2.83 + i * 2.33, 2.025);
  });
  card(s, 0.5, 2.85, 5.6, 0.75, { fill: OK, tr: 85 });
  text(s, "○ 取得する列を一つずつ書けば、列を追加しても結果の列の構成は変わらない", 0.7, 2.85, 5.3, 0.75,
    { fontSize: 14, bold: true, color: TEXT, valign: "middle" });
  text(s, "PostgreSQL と、文を保存して使い回すドライバー（prepared statement のキャッシュ）の組み合わせで起きる",
    0.5, 3.75, 5.6, 0.6, { fontSize: 11, color: MUTED });
  card(s, 6.4, 2.85, 3.1, 1.75);
  text(s, "103 件", 6.6, 2.92, 2.8, 0.5, { fontSize: 26, bold: true, color: BAD, valign: "middle" });
  text(s, "1 つの文だけ「SELECT *」に戻してデプロイしたとき、その文を使う要求が、切り替えまでの約 15 秒に失敗した数（あるシステムでの実測）",
    6.6, 3.45, 2.8, 1.1, { fontSize: 11, color: MUTED });
  takeaway(s, "「追加なら安全」は、コードの書き方による");
  s.addNotes("列の追加でも、古いコードが失敗することがある。PostgreSQL では、ドライバーが SQL の文を DB に保存して使い回す（prepared statement のキャッシュ）と、「SELECT *」の文は列を追加した後に結果の列の構成が変わり、DB がその文を実行しなくなる（SQLSTATE 0A000）。あるシステムで、1 つの文だけ「SELECT *」に戻してデプロイすると、その文を使う要求が、切り替えまでの約 15 秒の間に 103 件すべて失敗した。取得する列を一つずつ書けば、列を追加しても結果の列の構成は変わらない。");
}
{
  const s = content(SEC4, SEC4, "ロックの待ちで、ほかの要求が止まる");
  const flow = [
    ["migration が表のロックを取る（索引の作成・大量の行の書き換え）", { fill: DB, color: WHITE }],
    ["その表への書き込みが待たされる（新旧どちらのコードも）", { fill: OLD, tr: 75, color: TEXT }],
    ["要求のタイムアウトでエラーになる", { fill: BAD, color: WHITE }],
  ];
  flow.forEach(([t, o], i) => {
    box(s, 0.5 + i * 3.1, 1.45, 2.8, 1.0, t, Object.assign({ fontSize: 13, bold: true }, o));
    if (i < 2) arrow(s, 3.3 + i * 3.1, 1.95, 3.6 + i * 3.1, 1.95);
  });
  text(s, "対策の例", 0.5, 2.7, 4, 0.35, { fontSize: 14, bold: true });
  ["ロックを待つ時間に上限を設ける（例: PostgreSQL の lock_timeout）",
    "書き込みを止めずに索引を作る（例: CREATE INDEX CONCURRENTLY）",
    "大量の行の書き換えは、少しずつ行う"].forEach((t, i) => {
    badge(s, i + 1, 0.5, 3.12 + i * 0.5, 0.32, { fill: OK });
    text(s, t, 0.95, 3.1 + i * 0.5, 8.5, 0.36, { fontSize: 14, valign: "middle" });
  });
  takeaway(s, "大きな表の変更は、ロックを長く持たない形で行う");
  s.addNotes("migration は表のロックを取ることがある。索引の作成や大量の行の書き換えが長くかかると、その間、その表への書き込みが待たされ、新旧どちらのコードの要求もタイムアウトでエラーになる。対策の例は、ロックを待つ時間に上限を設けること（PostgreSQL の lock_timeout）、書き込みを止めずに索引を作ること（CREATE INDEX CONCURRENTLY）、大量の行の書き換えを少しずつ行うこと。");
}
