content.content:
1	// build.js の図を、Google Slides API の batchUpdate の要求に変換する。
2	// build.js が呼ぶ pptxgenjs の代わりに、呼び出しを記録する偽物を読み込ませ、
3	// 記録した図形を要求に変換して、スライドの範囲ごとに JSON のファイルに書き出す。
4	//
5	// 実行: node gslides.js <出力ディレクトリ> <最初のスライド>-<最後のスライド> [--rgb] [--master <id>] [--delete <id>]
6	//   --rgb     テーマの色を参照せず、RGB の値で書く（マスターの配色を変えられないとき）
7	//   --master  マスターの objectId。指定すると、マスターの配色をこの資料のテーマに変える要求を先頭に入れる
8	//   --delete  消すスライドの objectId（Drive が作った最初のスライド）
9	// ノートは別に書き出す: node gslides.js <出力ディレクトリ> notes <ノートの ID の JSON>
10	const fs = require("fs");
11	const path = require("path");
12	const Module = require("module");
13	
14	const PT = 72; // 1 インチのポイント数
15	// Google スライドのテキストの内側の余白。API では変えられないので、余白 0 の文字の箱をこの分だけ広げる
16	const PAD_X = 0.1, PAD_Y = 0.05;
17	const FONT = "Noto Sans JP";
18	const BULLET_INDENT = 16; // 箇条書きの本文の字下げ（ポイント）
19	
20	const SHAPES = {
21	  ROUNDED_RECTANGLE: "ROUND_RECTANGLE", RECTANGLE: "RECTANGLE", OVAL: "ELLIPSE",
22	  PENTAGON: "HOME_PLATE", CHEVRON: "CHEVRON", CAN: "CAN", LINE: "LINE",
23	};
24	const OVERLAY = new Set(["ELLIPSE", "CAN", "CHEVRON", "HOME_PLATE"]);
25	const SCHEME = {
26	  text1: "@DARK1", text2: "@DARK2", background1: "@LIGHT1", background2: "@LIGHT2",
27	  accent1: "@ACCENT1", accent2: "@ACCENT2", accent3: "@ACCENT3",
28	  accent4: "@ACCENT4", accent5: "@ACCENT5", accent6: "@ACCENT6",
29	};
30	const THEME_KEYS = {
31	  DARK1: "dk1", LIGHT1: "lt1", DARK2: "dk2", LIGHT2: "lt2",
32	  ACCENT1: "accent1", ACCENT2: "accent2", ACCENT3: "accent3",
33	  ACCENT4: "accent4", ACCENT5: "accent5", ACCENT6: "accent6",
34	  HYPERLINK: "hlink", FOLLOWED_HYPERLINK: "folHlink",
35	};
36	
37	class FakeSlide {
38	  constructor(master) { this.master = master; this.items = []; this.notes = ""; }
39	  addText(t, o) { this.items.push({ kind: "text", t, o }); }
40	  addShape(type, o) { this.items.push({ kind: "shape", type, o }); }
41	  addNotes(t) { this.notes = t; }
42	}
43	class FakePptx {
44	  constructor() { this.slides = []; this.masters = {}; this.SchemeColor = SCHEME; this.shapes = SHAPES; }
45	  defineSlideMaster(m) { this.masters[m.title] = m; }
46	  addSection() {}
47	  addSlide({ masterName }) { const s = new FakeSlide(this.masters[masterName]); this.slides.push(s); return s; }
48	  async writeFile() {}
49	}
50	
51	let captured = null;
52	const origLoad = Module._load;
53	Module._load = function (request, parent, isMain) {
54	  if (request === "pptxgenjs") return function () { const p = new FakePptx(); captured = { pres: p }; return p; };
55	  if (request.endsWith("apply_theme.js")) return { applyTheme: async (_f, theme) => { captured.theme = theme; } };
56	  return origLoad.apply(this, arguments);
57	};
58	
59	// ---- 引数 ----
60	const [outDir, range, ...rest] = process.argv.slice(2);
61	const flag = (n) => rest.includes(n);
62	const opt = (n) => { const i = rest.indexOf(n); return i >= 0 ? rest[i + 1] : undefined; };
63	process.env.PPTX_SKILL_DIR = process.env.PPTX_SKILL_DIR || "/nonexistent";
64	process.argv = [process.argv[0], path.join(__dirname, "build.js"), "unused.pptx"];
65	require("./build.js");
66	
67	setImmediate(async () => {
68	  await new Promise((r) => setTimeout(r, 50));
69	  const { pres, theme } = captured;
70	  fs.mkdirSync(outDir, { recursive: true });
71	  if (range === "notes") return writeNotes(pres, JSON.parse(fs.readFileSync(rest[0], "utf8")));
72	  const [a, b] = range.split("-").map(Number);
73	  const reqs = [];
74	  const master = opt("--master");
75	  if (master) reqs.push(colorSchemeRequest(master, theme));
76	  for (let n = a; n <= b; n++) reqs.push(...slideRequests(pres.slides[n - 1], n, theme, flag("--rgb")));
77	  const del = opt("--delete");
78	  if (del) reqs.push({ deleteObject: { objectId: del } });
79	  const file = path.join(outDir, `requests-${a}-${b}.json`);
80	  fs.writeFileSync(file, JSON.stringify(reqs));
81	  console.log(file, fs.statSync(file).size, "bytes", reqs.length, "requests");
82	});
83	
84	// ---- 変換 ----
85	const r3 = (v) => Math.round(v * 1000) / 1000;
86	const pt = (inch) => Math.round(inch * PT * 100) / 100;
87	function hexRgb(hex) {
88	  const n = parseInt(hex, 16);
89	  return { red: r3(((n >> 16) & 255) / 255), green: r3(((n >> 8) & 255) / 255), blue: r3((n & 255) / 255) };
90	}
91	function color(c, theme, rgb) {
92	  if (c.startsWith("@")) {
93	    const k = c.slice(1);
94	    return rgb ? { rgbColor: hexRgb(theme.colors[THEME_KEYS[k]]) } : { themeColor: k };
95	  }
96	  return { rgbColor: hexRgb(c) };
97	}
98	function colorSchemeRequest(masterId, theme) {
99	  const colors = Object.entries(THEME_KEYS).map(([type, k]) => ({ type, color: hexRgb(theme.colors[k]) }));
100	  return { updatePageProperties: { objectId: masterId, pageProperties: { colorScheme: { colors } }, fields: "colorScheme.colors" } };
101	}
102	function geom(page, x, y, w, h) {
103	  return {
104	    pageObjectId: page,
105	    size: { width: { magnitude: pt(w), unit: "PT" }, height: { magnitude: pt(h), unit: "PT" } },
106	    transform: { scaleX: 1, scaleY: 1, translateX: pt(x), translateY: pt(y), unit: "PT" },
107	  };
108	}
109	const ALIGN = { left: "START", center: "CENTER", right: "END" };
110	const VALIGN = { top: "TOP", middle: "MIDDLE", bottom: "BOTTOM" };
111	const DASH = { dash: "DASH", sysDot: "DOT", sysDash: "DASH" };
112	
113	function slideRequests(slide, n, theme, rgb) {
114	  const page = `sl_${String(n).padStart(2, "0")}`;
115	  // スライド番号は作らない。API ではレイアウトのスライド番号のプレースホルダーをスライドに作れないため、
116	  // Google スライドのメニューの「挿入 > スライド番号」で付ける
117	  const reqs = [{ createSlide: { objectId: page, insertionIndex: n - 1, slideLayoutReference: { predefinedLayout: "BLANK" } } }];
118	  const bg = slide.master.background && slide.master.background.color;
119	  if (bg && bg !== "FFFFFF") {
120	    reqs.push({ updatePageProperties: { objectId: page, pageProperties: { pageBackgroundFill: { solidFill: { color: color(bg, theme, rgb) } } }, fields: "pageBackgroundFill.solidFill.color" } });
121	  }
122	  let k = 0;
123	  const id = () => `e${String(n).padStart(2, "0")}_${String(++k).padStart(2, "0")}`;
124	  const col = (c) => color(c, theme, rgb);
125	
126	  for (const it of slide.items) {
127	    let o = it.o;
128	    if (it.kind === "text" && o.placeholder) {
129	      const ph = slide.master.objects.find((x) => x.placeholder.options.name === o.placeholder).placeholder.options;
130	      o = Object.assign({}, ph, { isTextBox: true });
131	    }
132	    if (it.kind === "shape" && it.type === SHAPES.LINE) { reqs.push(...lineRequests(id(), page, o, col)); continue; }
133	    if (it.kind === "text" && OVERLAY.has(o.shape)) {
134	      // Google スライドは円・円柱・山形の中の文字を、図形の内側の狭い四角に収めるので、
135	      // 図形と文字を分け、図形の外形に合わせた文字の箱を上に重ねる
136	      slide.items.splice(slide.items.indexOf(it) + 1, 0,
137	        { kind: "text", t: it.t, o: Object.assign({}, o, { shape: undefined, overlay: true }) });
138	      it.kind = "shape"; it.type = o.shape;
139	    }
140	    const oid = id();
141	    const isBox = it.kind === "text" && !o.shape;
142	    let { x, y, w, h } = o;
143	    const margin = o.margin === undefined ? (isBox && !o.overlay ? 0 : 6) : o.margin;
144	    if (isBox && o.overlay) {
145	      const [mt, mr, mb, ml] = (Array.isArray(margin) ? margin : [margin, margin, margin, margin]).map((m) => m / PT);
146	      x += ml; y += mt; w -= ml + mr; h -= mt + mb;
147	    }
148	    if (isBox && (o.overlay || margin === 0)) { x -= PAD_X; y -= PAD_Y; w += 2 * PAD_X; h += 2 * PAD_Y; }
149	    let shapeType = isBox ? "TEXT_BOX" : (it.kind === "shape" ? it.type : o.shape);
150	    // Google スライドでは角の丸みを変えられないので、大きな箱は角の丸い四角にしない
151	    if (shapeType === "ROUND_RECTANGLE" && Math.min(w, h) > 1.0) shapeType = "RECTANGLE";
152	    reqs.push({ createShape: { objectId: oid, shapeType, elementProperties: geom(page, x, y, w, h) } });
153	
154	    const sp = {}, fields = [];
155	    if (!isBox) {
156	      const f = o.fill || {};
157	      sp.shapeBackgroundFill = { solidFill: { color: col(f.color || SCHEME.background1) } };
158	      if (f.transparency) sp.shapeBackgroundFill.solidFill.alpha = r3(1 - f.transparency / 100);
159	      fields.push("shapeBackgroundFill");
160	      if (o.line && o.line.color) {
161	        sp.outline = { outlineFill: { solidFill: { color: col(o.line.color) } }, weight: { magnitude: o.line.width || 1, unit: "PT" } };
162	        if (o.line.dashType) sp.outline.dashStyle = DASH[o.line.dashType];
163	      } else sp.outline = { propertyState: "NOT_RENDERED" };
164	      fields.push("outline");
165	    }
166	    const va = VALIGN[o.valign || (isBox && !o.overlay ? "top" : "middle")];
167	    // 文字の無い図形には、縦の位置を指定しない（要求を短くするため）
168	    if (it.kind === "text" && (!isBox || va !== "TOP")) { sp.contentAlignment = va; fields.push("contentAlignment"); }
169	    if (fields.length) reqs.push({ updateShapeProperties: { objectId: oid, shapeProperties: sp, fields: fields.join(",") } });
170	
171	    if (it.kind === "text") reqs.push(...textRequests(oid, it.t, o, isBox, col));
172	  }
173	  return reqs;
174	}
