176	function lineRequests(oid, page, o, col) {
177	  const { x, y, w, h } = o;
178	  const e = geom(page, x, y, w, h);
179	  // 右から左・下から上の線は、拡大率を負にして向きを反転する
180	  if (o.flipH) { e.transform.scaleX = -1; e.transform.translateX = pt(x + w); }
181	  if (o.flipV) { e.transform.scaleY = -1; e.transform.translateY = pt(y + h); }
182	  const l = o.line;
183	  const lp = { lineFill: { solidFill: { color: col(l.color) } }, weight: { magnitude: l.width || 1, unit: "PT" },
184	    dashStyle: l.dashType ? DASH[l.dashType] : "SOLID",
185	    endArrow: l.endArrowType ? "FILL_ARROW" : "NONE", startArrow: l.beginArrowType ? "FILL_ARROW" : "NONE" };
186	  return [
187	    { createLine: { objectId: oid, category: "STRAIGHT", elementProperties: e } },
188	    { updateLineProperties: { objectId: oid, lineProperties: lp, fields: "lineFill,weight,dashStyle,endArrow,startArrow" } },
189	  ];
190	}
191	
192	function textRequests(oid, t, o, isBox, col) {
193	  const runs = typeof t === "string" ? [{ text: t, options: {} }] : t;
194	  let full = "";
195	  const spans = [];
196	  runs.forEach((r) => {
197	    const ro = Object.assign({}, r.options);
198	    const start = full.length;
199	    full += r.text + (ro.breakLine ? "\n" : "");
200	    // 改行も同じ範囲に含める。含めないと改行の文字が既定の大きさのまま残り、その行が高くなる
201	    spans.push({ start, end: full.length, o: ro });
202	  });
203	  if (!full) return [];
204	  const reqs = [{ insertText: { objectId: oid, text: full } }];
205	  const styleOf = (ro) => {
206	    const s = { fontFamily: FONT, fontSize: { magnitude: ro.fontSize || o.fontSize || 18, unit: "PT" } };
207	    // 新しい箱の文字は太字ではないので、太字のときだけ指定する（要求を短くするため）
208	    if (ro.bold !== undefined ? ro.bold : o.bold) s.bold = true;
209	    s.foregroundColor = { opaqueColor: col(ro.color || o.color || SCHEME.text1) };
210	    if (ro.hyperlink) s.link = { url: ro.hyperlink.url };
211	    return s;
212	  };
213	  const styles = spans.map((sp) => styleOf(sp.o));
214	  const same = styles.every((s) => JSON.stringify(s) === JSON.stringify(styles[0]));
215	  const fieldsOf = (s) => "fontFamily,fontSize" + (s.bold ? ",bold" : "") + ",foregroundColor" + (s.link ? ",link" : "");
216	  if (same) {
217	    reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "ALL" }, style: styles[0], fields: fieldsOf(styles[0]) } });
218	  } else {
219	    spans.forEach((sp, i) => {
220	      if (sp.end === sp.start) return;
221	      reqs.push({ updateTextStyle: { objectId: oid, textRange: { type: "FIXED_RANGE", startIndex: sp.start, endIndex: sp.end }, style: styles[i], fields: fieldsOf(styles[i]) } });
222	    });
223	  }
224	  const ps = {}, pf = [];
225	  const al = ALIGN[o.align || (isBox && !o.overlay ? "left" : "center")];
226	  if (!isBox || al !== "START") { ps.alignment = al; pf.push("alignment"); }
227	  if (o.paraSpaceAfter) { ps.spaceBelow = { magnitude: o.paraSpaceAfter, unit: "PT" }; pf.push("spaceBelow"); }
228	  if (pf.length) reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" }, style: ps, fields: pf.join(",") } });
229	  if (spans.some((sp) => sp.o.bullet)) {
230	    reqs.push({ createParagraphBullets: { objectId: oid, textRange: { type: "ALL" }, bulletPreset: "BULLET_DISC_CIRCLE_SQUARE" } });
231	    // 字下げのデフォルト値は大きく、狭い箱では行が折り返されるので、記号の幅だけにする
232	    reqs.push({ updateParagraphStyle: { objectId: oid, textRange: { type: "ALL" },
233	      style: { indentFirstLine: { magnitude: 0, unit: "PT" }, indentStart: { magnitude: BULLET_INDENT, unit: "PT" } },
234	      fields: "indentFirstLine,indentStart" } });
235	  }
236	  return reqs;
237	}
